using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
using LWS.TruckHockey;
using LWS.TruckSports;
namespace LWS.TruckAirHockey {
public enum AirHockeyMode {PlayerAI,SharedKeyboard,SeparateControllers,KeyboardController,AIVsAI,SharedController,Custom}
[DefaultExecutionOrder(-100)]public sealed class AirHockeyMatch:MonoBehaviour {
 public const string SetupKey="TruckAirHockey.Setup.v1";public HockeyPlayer[] players={new HockeyPlayer{name="Blue",color=new Color(.15f,.8f,1),source=HockeySource.Keyboard,forward=Key.W,left=Key.A,back=Key.S,right=Key.D},new HockeyPlayer{name="Orange",color=new Color(1,.55f,.13f),source=HockeySource.AI,forward=Key.UpArrow,left=Key.LeftArrow,back=Key.DownArrow,right=Key.RightArrow}};
 public AirHockeyMode mode;public AirHockeyTruck[] trucks;public AirHockeyAI[] agents;public Rigidbody puck;public AirHockeyPuck puckContact;public Collider[] truckBarriers;public AirHockeyMenus menus;public SportsSettings settings;public SportsFeedback feedback;public Renderer[] paint;public float goalLine=12,goalHalfWidth=2.1f,halfWidth=6,cornerRadius=2.5f,radius=.43f;public readonly AirHockeyRules rules=new AirHockeyRules();
 public bool InMatch{get;private set;}public bool MenuOpen=>menus.Screen!=AirHockeyScreen.Play;public int Revision{get;private set;}public int LastTouch=-1;public int Recoveries{get;private set;}public string Notice{get;private set;}="FIRST TO 7 • Trucks stay in their own halves";public readonly SportsDeviceInput input=new SportsDeviceInput();
 bool segment;Vector3 previous;int opening;float invalid,stationary,trapped;Collider puckCollider;readonly Collider[] query=new Collider[64];readonly RaycastHit[] escapeHits=new RaycastHit[64];Material[] colors;readonly List<Material>[] cabPaint={new List<Material>(),new List<Material>()};
 public bool Ready(int i){var p=players[i];return p.source==HockeySource.AI||p.source==HockeySource.Keyboard&&Keyboard.current!=null&&Keyboard.current.enabled||p.controller&&p.pad!=null&&p.pad.added&&p.pad.enabled;}
 public bool DevicesReady=>ValidateOwnership(out _)&&Ready(0)&&Ready(1);public bool AllAI=>players[0].source==HockeySource.AI&&players[1].source==HockeySource.AI;
 public bool ValidateOwnership(out string reason){for(int i=0;i<2;i++){var p=players[i];if(p.source==HockeySource.Keyboard){var keys=new[]{p.forward,p.left,p.back,p.right};for(int k=0;k<4;k++){if(keys[k]==Key.None||keys[k]==Key.Escape){reason="Assign gameplay keys; Escape is reserved.";return false;}for(int j=0;j<k;j++)if(keys[k]==keys[j]){reason="Duplicate gameplay key.";return false;}if(i==1&&players[0].source==HockeySource.Keyboard&&(keys[k]==players[0].forward||keys[k]==players[0].back||keys[k]==players[0].left||keys[k]==players[0].right)){reason="Keyboard sources overlap.";return false;}}}}
  var a=players[0];var b=players[1];if(a.controller&&b.controller&&a.pad!=null&&a.pad==b.pad&&(a.source==HockeySource.WholeController||b.source==HockeySource.WholeController||a.source==b.source)){reason="Each whole pad or separate stick has one owner.";return false;}reason="";return true;}
 void Awake(){puckCollider=puck.GetComponent<Collider>();foreach(var barrier in truckBarriers)Physics.IgnoreCollision(barrier,puckCollider);Freeze(true);colors=new Material[paint.Length];for(int i=0;i<paint.Length;i++){colors[i]=new Material(paint[i].sharedMaterial);paint[i].sharedMaterial=colors[i];}for(int i=0;i<2;i++)foreach(var r in trucks[i].GetComponentsInChildren<MeshRenderer>())if(r.name=="Cab"&&r!=paint[i])foreach(var material in r.materials)cabPaint[i].Add(material);}
 void Start(){Load();Dirty();menus.Show(AirHockeyScreen.Setup);}void OnEnable(){InputSystem.onDeviceChange+=DeviceChanged;}void OnDisable(){InputSystem.onDeviceChange-=DeviceChanged;feedback.StopAll();}void OnDestroy(){foreach(var c in colors)Destroy(c);foreach(var list in cabPaint)foreach(var c in list)Destroy(c);Time.timeScale=1;}
 public void Dirty(){Revision++;menus?.Dirty();}public void Gate(){foreach(var p in players)p.released=false;foreach(var t in trucks)t.Stop();menus?.Gate();}
 public void Configure(AirHockeyMode selection){mode=selection;for(int i=0;i<2;i++){var p=players[i];var old=p.source;p.source=selection==AirHockeyMode.AIVsAI?HockeySource.AI:selection==AirHockeyMode.SharedKeyboard?HockeySource.Keyboard:selection==AirHockeyMode.SeparateControllers?HockeySource.WholeController:selection==AirHockeyMode.SharedController?(i==0?HockeySource.LeftStick:HockeySource.RightStick):selection==AirHockeyMode.KeyboardController?(i==0?HockeySource.Keyboard:HockeySource.WholeController):i==0?HockeySource.Keyboard:HockeySource.AI;if(old!=p.source)p.pad=null;}Gate();Dirty();Save();}
 public bool Assign(int i,Gamepad pad){if(i<0||i>1||!players[i].controller||pad==null||!pad.added||!pad.enabled)return false;var old=players[i].pad;players[i].pad=pad;if(!ValidateOwnership(out _)){players[i].pad=old;return false;}input.Forget(pad);Gate();Dirty();Save();return true;}
 public void Unassign(int i){players[i].pad=null;Gate();Dirty();}public void CycleSource(int i){mode=AirHockeyMode.Custom;players[i].source=(HockeySource)(((int)players[i].source+1)%5);players[i].pad=null;Gate();Dirty();Save();}
 public bool Neutral(int i){if(!Ready(i))return false;var p=players[i];if(p.source==HockeySource.AI)return true;if(p.source==HockeySource.Keyboard)return !SportsDeviceInput.KeyHeld(p.forward)&&!SportsDeviceInput.KeyHeld(p.back)&&!SportsDeviceInput.KeyHeld(p.left)&&!SportsDeviceInput.KeyHeld(p.right);return Drive(i).sqrMagnitude<.01f&&!p.pad.startButton.isPressed&&!p.pad.buttonSouth.isPressed;}
 public Vector2 Drive(int i){var p=players[i];if(!Ready(i))return Vector2.zero;if(p.source==HockeySource.AI)return Vector2.zero;if(p.source==HockeySource.Keyboard)return new Vector2((SportsDeviceInput.KeyHeld(p.right)?1:0)-(SportsDeviceInput.KeyHeld(p.left)?1:0),(SportsDeviceInput.KeyHeld(p.forward)?1:0)-(SportsDeviceInput.KeyHeld(p.back)?1:0));if(p.source==HockeySource.LeftStick||p.source==HockeySource.RightStick){var v=p.source==HockeySource.LeftStick?p.pad.leftStick.ReadValue():p.pad.rightStick.ReadValue();return new Vector2(Mathf.Abs(v.x)<.16f?0:v.x,Mathf.Abs(v.y)<.16f?0:v.y);}var stick=p.pad.leftStick.ReadValue();float gas=p.pad.rightTrigger.ReadValue()-p.pad.leftTrigger.ReadValue();return new Vector2(Mathf.Abs(stick.x)<.16f?0:stick.x,Mathf.Abs(gas)<.1f?0:gas);}
 void DeviceChanged(InputDevice device,InputDeviceChange change){Dirty();foreach(var p in players)if(p.controller&&p.pad==device){input.Forget((Gamepad)device);Gate();if(InMatch&&rules.Phase!=AirHockeyPhase.Finished&&(change==InputDeviceChange.Removed||change==InputDeviceChange.Disconnected||change==InputDeviceChange.Disabled))Pause(true);break;}}
 public bool StartMatch(bool rematch=false){if(!DevicesReady){menus.Show(AirHockeyScreen.Join);return false;}if(rematch)opening=1-opening;else opening=0;Save();InMatch=true;Recoveries=0;rules.Start(opening);ResetPositions();menus.Show(AirHockeyScreen.Play);Time.timeScale=1;Notice=players[opening].name+" opens • FIRST TO 7";return true;}
 void Freeze(bool value){foreach(var truck in trucks){if(value&&!truck.body.isKinematic){truck.body.linearVelocity=truck.body.angularVelocity=Vector3.zero;}truck.body.isKinematic=value;truck.Stop();}if(value&&!puck.isKinematic)puck.linearVelocity=puck.angularVelocity=Vector3.zero;puck.isKinematic=value;}
 public void ResetPositions(){Freeze(true);puck.position=new Vector3((rules.Server==0?-1:1)*3,.22f,0);puck.rotation=Quaternion.identity;for(int i=0;i<2;i++){trucks[i].ResetBody(new Vector3(i==0?-6:6,.36f,0),Quaternion.Euler(0,i==0?90:-90,0));colors[i].color=players[i].color;foreach(var material in cabPaint[i])material.color=players[i].color;}foreach(var agent in agents)agent.ResetPlan();LastTouch=-1;puckContact.ClearContacts();segment=false;invalid=stationary=trapped=0;Gate();Physics.SyncTransforms();}
 public void Pause(bool disconnected=false){if(!InMatch||rules.Phase==AirHockeyPhase.Finished)return;rules.Pause();Time.timeScale=0;Gate();feedback.StopAll();menus.Show(disconnected?AirHockeyScreen.Disconnect:AirHockeyScreen.Pause);}
 public void Resume(){if(!DevicesReady){Pause(true);return;}rules.Resume();Time.timeScale=1;Gate();menus.Show(AirHockeyScreen.Play);}public void ChangeSetup(){InMatch=false;Time.timeScale=1;Freeze(true);feedback.StopAll();menus.Show(AirHockeyScreen.Setup);}
 public void Recovery(){if(!rules.Live)return;Recoveries++;rules.Serve(rules.Server);ResetPositions();Notice="PUCK RECOVERY • SCORE PRESERVED • "+players[rules.Server].name+" serves";Debug.Log("AH_RECOVERY");}
 bool Blocked(Vector3 point){int n=Physics.OverlapSphereNonAlloc(point,radius*.93f,query,~0,QueryTriggerInteraction.Ignore);var all=n==query.Length?Physics.OverlapSphere(point,radius*.93f,~0,QueryTriggerInteraction.Ignore):query;if(n==query.Length)n=all.Length;for(int i=0;i<n;i++){var c=all[i];if(c==puckCollider||Array.IndexOf(truckBarriers,c)>=0)continue;if(c.attachedRigidbody!=null||c.name.StartsWith("Rail")||c.name.StartsWith("Goal"))return true;}return false;}
 bool NoEscape(out bool staticTrap){staticTrap=true;bool trapped=true;for(int i=0;i<16;i++){var d=Quaternion.Euler(0,i*22.5f,0)*Vector3.forward;int n=Physics.SphereCastNonAlloc(puck.position,radius*.92f,d,escapeHits,1.4f,~0,QueryTriggerInteraction.Ignore);var hits=n==escapeHits.Length?Physics.SphereCastAll(puck.position,radius*.92f,d,1.4f,~0,QueryTriggerInteraction.Ignore):escapeHits;if(n==escapeHits.Length)n=hits.Length;bool blocked=false,wall=false;for(int h=0;h<n;h++){var c=hits[h].collider;if(c==puckCollider||Array.IndexOf(truckBarriers,c)>=0)continue;if(c.attachedRigidbody!=null||c.name.StartsWith("Rail")||c.name.StartsWith("Goal")){blocked=true;if(c.attachedRigidbody==null)wall=true;}}if(!blocked&&!Blocked(puck.position+d*.7f)){trapped=false;staticTrap=false;break;}if(!wall)staticTrap=false;}return trapped;} bool InvalidPuck(){var p=puck.position;bool goalChannel=Mathf.Abs(p.z)<goalHalfWidth&&Mathf.Abs(p.x)<=goalLine+2.6f;bool bad=Mathf.Abs(p.x)>goalLine+2.6f||Mathf.Abs(p.z)>halfWidth+.65f||Mathf.Abs(p.y-.22f)>.6f||!goalChannel&&!AirHockeyArena.Contains(p,goalLine,halfWidth,cornerRadius,-.1f);int n=Physics.OverlapSphereNonAlloc(p,radius*.8f,query,~0,QueryTriggerInteraction.Ignore);for(int i=0;i<n;i++){var c=query[i];if(c.attachedRigidbody==null&&Array.IndexOf(truckBarriers,c)<0&&Physics.ComputePenetration(puckCollider,p,puck.rotation,c,c.transform.position,c.transform.rotation,out _,out float depth)&&depth>.15f)bad=true;}invalid=bad?invalid+Time.fixedDeltaTime:0;stationary=puck.linearVelocity.sqrMagnitude<.0064f?stationary+Time.fixedDeltaTime:0;bool pin=stationary>4&&NoEscape(out bool staticTrap)&&(staticTrap||puckContact.ActiveContacts==2&&Mathf.Abs(trucks[0].throttle)>.25f&&Mathf.Abs(trucks[1].throttle)>.25f);trapped=pin?trapped+Time.fixedDeltaTime:0;return invalid>.6f||trapped>6;}
 void Update(){input.Sample();if(menus.Screen==AirHockeyScreen.Join||menus.Screen==AirHockeyScreen.Disconnect)foreach(var pad in Gamepad.all)if(input.Down(pad,2))for(int i=0;i<2;i++)if(players[i].controller&&!Ready(i)&&Assign(i,pad)){if(players[i].source==HockeySource.WholeController)break;}
  bool pause=SportsDeviceInput.KeyDown(Key.Escape);foreach(var p in players)if(p.controller&&input.Down(p.pad,4))pause=true;if(AllAI)foreach(var pad in Gamepad.all)pause|=input.Down(pad,4);if(pause){if(menus.Screen==AirHockeyScreen.Play)Pause();else menus.Back();return;}if(!InMatch||!rules.Live||MenuOpen)return;for(int i=0;i<2;i++){var p=players[i];if(p.source==HockeySource.AI)continue;if(!Ready(i)){Pause(true);return;}if(!p.released){trucks[i].Stop();if(Neutral(i))p.released=true;continue;}var v=Drive(i);v.x*=settings.sensitivity;trucks[i].Control(v);}}
 void FixedUpdate(){if(!InMatch||MenuOpen)return;if(rules.Live){if(segment&&rules.Step(previous,puck.position,goalLine,goalHalfWidth,radius)){Freeze(true);segment=false;Notice="GOAL • "+players[rules.Scorer].name+(LastTouch>=0&&LastTouch!=rules.Scorer?" • own goal by "+players[LastTouch].name:"");feedback.Play(5,0,true);menus.Celebrate(false);Debug.Log("AH_PHYSICAL_GOAL scorer="+rules.Scorer+" lastTouch="+LastTouch+" score="+rules.Score[0]+":"+rules.Score[1]);if(rules.Phase==AirHockeyPhase.Finished){feedback.StopMotors();menus.Show(AirHockeyScreen.Result);feedback.Play(6,0,true);menus.Celebrate(true);Time.timeScale=0;}return;}if(InvalidPuck()){Recovery();return;}previous=puck.position;segment=true;}
  else{var before=rules.Phase;if(rules.Tick(Time.fixedDeltaTime)){if(before==AirHockeyPhase.Goal){ResetPositions();Notice=players[rules.Server].name+" serves";}else if(rules.Live){Freeze(false);Gate();previous=puck.position;segment=false;feedback.Play(4,0,true);Notice=players[rules.Server].name+" SERVE • GO!";}}}}
 [Serializable]sealed class Saved{public AirHockeyMode mode;public Slot[] slots;}[Serializable]sealed class Slot{public string name;public Color color;public HockeySource source;public HockeyDifficulty difficulty;public int pad;}
 public void Save(){var s=new Saved{mode=mode,slots=new Slot[2]};for(int i=0;i<2;i++){var p=players[i];s.slots[i]=new Slot{name=p.name,color=p.color,source=p.source,difficulty=p.difficulty,pad=p.pad?.deviceId??-1};}PlayerPrefs.SetString(SetupKey,JsonUtility.ToJson(s));PlayerPrefs.Save();}
 void Load(){try{if(!PlayerPrefs.HasKey(SetupKey))return;var s=JsonUtility.FromJson<Saved>(PlayerPrefs.GetString(SetupKey));if(s?.slots==null||s.slots.Length!=2)return;mode=s.mode;for(int i=0;i<2;i++){var p=players[i];var a=s.slots[i];p.name=string.IsNullOrWhiteSpace(a.name)?"Player "+(i+1):a.name;p.color=a.color;p.source=a.source;p.difficulty=a.difficulty;p.pad=InputSystem.GetDeviceById(a.pad) as Gamepad;}}catch(Exception){Debug.LogWarning("Air Hockey setup invalid; defaults retained.");}}
}
